<details @keydown.escape.prevent.stop="$el.open=false;$el.querySelector('summary').focus()" class="qms-folder-actions" @click.outside="$el.open=false"><summary :aria-label="'Actions for folder ' + folder.name">&hellip;</summary><div class="qms-action-popover"><button type="button" @click="$el.closest('details').open=false;$el.closest('details').querySelector('summary').focus();openBrowseFolder(folder)">Open</button><button type="button" @click="$el.closest('details').open=false;$el.closest('details').querySelector('summary').focus();toggleFolderStar(folder)" x-text="folder.isStarred ? 'Unstar' : 'Star'"></button><button type="button" @click="$el.closest('details').open=false;$el.closest('details').querySelector('summary').focus();inspectFolder(folder)">View Details</button></div></details>
